254	
255	    /**
256	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
257	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
258	     *
259	     * @param fields the submitted owner fields
260	     * @throws RequiredFieldsMissingException if any of firstName, lastName, city or telephone is
261	     *                                        {@code null} or blank, or if address is blank after
262	     *                                        normalization
263	     */
264	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
265	        List<String> missing = new ArrayList<>();
266	        if (isBlank(fields.getFirstName())) {
267	            missing.add("firstName");
268	        }
269	        if (isBlank(fields.getLastName())) {
270	            missing.add("lastName");
271	        }
272	        if (isBlank(normalizeAddress(fields.getAddress()))) {
273	            missing.add("address");
274	        }
275	        if (isBlank(fields.getCity())) {
276	            missing.add("city");
277	        }
278	        if (isBlank(fields.getTelephone())) {
279	            missing.add("telephone");
280	        }
281	        if (!missing.isEmpty()) {
282	            throw new RequiredFieldsMissingException(missing);
283	        }
284	    }
285	
286	    private boolean isBlank(String value) {
287	        return value == null || value.isBlank();
288	    }
289	
290	    /**
291	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
292	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
293	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
294	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
295	     *
296	     * @param telephone the raw telephone value from the request
297	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
298	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
299	     */
300	    private String normalizeTelephone(String telephone) {
301	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
302	        String digits;
303	        if (cleaned.startsWith("+")) {
304	            digits = cleaned.substring(1);
305	        } else {
306	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
307	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
308	            digits = "61" + national;
309	        }
310	        if (!digits.matches("[0-9]{8,15}")) {
311	            throw new InvalidTelephoneException(cleaned);
312	        }
313	        return "+" + digits;
314	    }
315	
316	    /**
317	     * Normalizes a submitted email address. A {@code null} email is left absent (the field is optional).
318	     * When present, it must be a syntactically valid address; the stored and returned value is trimmed and
319	     * lower-cased.
320	     *
321	     * @param email the raw email value from the request, or {@code null} if omitted
322	     * @return the lower-cased email, or {@code null} if none was supplied
323	     * @throws InvalidEmailException if a non-null email is not a syntactically valid address
324	     */
325	    private String normalizeEmail(String email) {
326	        if (email == null) {
327	            return null;
328	        }
329	        String trimmed = email.strip();
330	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
331	            throw new InvalidEmailException(email);
332	        }
333	        return trimmed.toLowerCase(Locale.ROOT);
334	    }
335	
336	    /**
337	     * Normalizes a submitted address into the form that is stored and returned. Leading and trailing
338	     * whitespace is removed, internal runs of whitespace are collapsed to a single space, the value is
339	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
340	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). Abbreviations are only expanded when they form a whole
341	     * word, so an address such as {@code '  12  main  st '} normalizes to {@code '12 MAIN STREET'}.
342	     *
343	     * @param address the raw address value from the request (may be {@code null})
344	     * @return the normalized address, or an empty string when {@code address} is {@code null} or blank
345	     */
346	    private String normalizeAddress(String address) {
347	        if (address == null) {
348	            return "";
349	        }
350	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
351	        if (collapsed.isEmpty()) {
352	            return "";
353	        }
354	        String[] tokens = collapsed.split(" ");
355	        StringBuilder sb = new StringBuilder(collapsed.length());
356	        for (int i = 0; i < tokens.length; i++) {
357	            if (i > 0) {
358	                sb.append(' ');
359	            }
360	            sb.append(expandAddressAbbreviation(tokens[i]));
361	        }
362	        return sb.toString();
363	    }
364	
365	    /**
366	     * Expands a single upper-cased address token from its common abbreviation to its full form, or
367	     * returns the token unchanged when it is not a recognised abbreviation.
368	     *
369	     * @param token an upper-cased whole-word address token
370	     * @return the expanded form ({@code STREET}, {@code ROAD}, {@code AVENUE}) or the original token
371	     */
372	    private String expandAddressAbbreviation(String token) {
373	        return switch (token) {
374	            case "ST" -> "STREET";
375	            case "RD" -> "ROAD";
376	            case "AVE" -> "AVENUE";
377	            default -> token;
378	        };
379	    }
380	
381	    /**
382	     * Rejects a create request whose normalized telephone is already used by another owner. Owners store
383	     * their telephone in normalized E.164 form, so an exact string comparison of E.164 values is sufficient.
384	     *
385	     * @param telephone the normalized (E.164) telephone of the owner being created
386	     * @throws DuplicateTelephoneException if any existing owner already uses the telephone
387	     */
388	    /**
389	     * Builds the customer code assigned to a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
390	     * where {@code CITY3} is the upper-cased first three letters of the owner's city, {@code LAST3} the
391	     * upper-cased first three letters of the owner's last name, and {@code NNNN} a per-city 4-digit
392	     * zero-padded sequence equal to one more than the number of owners already in that city (e.g.
393	     * {@code 'SYD-SMI-0007'}). The code is computed before the new owner is persisted, so the count excludes
394	     * it. Cities are matched case-insensitively so that owners sharing a {@code CITY3} prefix share a sequence.
395	     *
396	     * @param city the owner's city
397	     * @param lastName the owner's last name
398	     * @return the assigned customer code
399	     */
400	    private String generateCustomerCode(String city, String lastName) {
401	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
402	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
403	        int sequence = (int) this.clinicService.findAllOwners().stream()
404	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
405	            .count() + 1;
406	        return String.format("%s-%s-%04d", city3, last3, sequence);
407	    }
408	
409	    /**
410	     * Counts how many existing owners already share the given first name and last name, compared
411	     * case-insensitively. The count is taken before the new owner is persisted, so it excludes the
412	     * owner being created.
413	     *
414	     * @param firstName the first name of the owner being created
415	     * @param lastName the last name of the owner being created
416	     * @return the number of existing owners with the same first and last name (case-insensitively)
417	     */
418	    private int countNamesakes(String firstName, String lastName) {
419	        return (int) this.clinicService.findAllOwners().stream()
420	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
421	                && lastName.equalsIgnoreCase(existing.getLastName()))
422	            .count();
423	    }
424	
425	    /**
426	     * The maximum number of owners permitted in a single city. A create request whose city already
427	     * holds this many owners is rejected.
428	     */
429	    private static final int CITY_OWNER_LIMIT = 50;
430	
431	    /**
432	     * Rejects a create request whose city already contains {@link #CITY_OWNER_LIMIT} or more owners.
433	     * Cities are matched case-insensitively, mirroring the per-city customer-code sequence, so owners
434	     * differing only in the casing of their city share one capacity pool. The count is taken before the
435	     * new owner is persisted, so it excludes the owner being created.
436	     *
437	     * @param city the city of the owner being created
438	     * @throws CityOwnerLimitExceededException if the city already holds the maximum number of owners
439	     */
440	    private void rejectCityAtCapacity(String city) {
441	        long existing = this.clinicService.findAllOwners().stream()
442	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
443	            .count();
444	        if (existing >= CITY_OWNER_LIMIT) {
445	            throw new CityOwnerLimitExceededException(city, CITY_OWNER_LIMIT);
446	        }
447	    }
448	
449	    /**
450	     * The maximum number of owners permitted to be created in a single day. A create request whose
451	     * registration date already holds this many owners is rejected.
452	     */
453	    private static final int DAILY_OWNER_LIMIT = 100;
454	
455	    /**
456	     * Rejects a create request when {@link #DAILY_OWNER_LIMIT} or more owners have already been created
457	     * on the same day, compared by {@code registrationDate}. The count is taken before the new owner is
458	     * persisted, so it excludes the owner being created.
459	     *
460	     * @param registrationDate the registration date of the owner being created
461	     * @throws DailyOwnerLimitExceededException if the day already holds the maximum number of owners
462	     */
463	    /**
464	     * Adjusts an effective registration date so that it always falls on a business day. When the given
465	     * date is a Saturday or Sunday it is rolled forward to the following Monday; a weekday is returned
466	     * unchanged. This applies equally to a date supplied in the request and to a date defaulted to the
467	     * server date, and the adjusted value is what becomes the owner's {@code registrationDate}, so every
468	     * value derived from it (the membership number's year segment, the daily create-limit count) uses the
469	     * business-day-adjusted date.
470	     *
471	     * @param date the effective registration date, supplied or defaulted
472	     * @return the same date when it is a weekday, otherwise the next Monday
473	     */
474	    private LocalDate rollToBusinessDay(LocalDate date) {
475	        DayOfWeek day = date.getDayOfWeek();
476	        if (day == DayOfWeek.SATURDAY) {
477	            return date.plusDays(2);
478	        }
479	        if (day == DayOfWeek.SUNDAY) {
480	            return date.plusDays(1);
481	        }
482	        return date;
483	    }
484	
485	    private void rejectDailyLimitReached(LocalDate registrationDate) {
486	        long existing = this.clinicService.findAllOwners().stream()
487	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
488	            .count();
489	        if (existing >= DAILY_OWNER_LIMIT) {
490	            throw new DailyOwnerLimitExceededException(registrationDate, DAILY_OWNER_LIMIT);
491	        }
492	    }
493	
494	    private void rejectDuplicateTelephone(String telephone) {
495	        boolean taken = this.clinicService.findAllOwners().stream()
496	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
497	        if (taken) {
498	            throw new DuplicateTelephoneException(telephone);
499	        }
500	    }
501	
502	    /**
503	     * Rejects a create request whose owner shares both last name and address with an existing owner.
504	     * Last name and address are compared case-insensitively with runs of whitespace collapsed to a
505	     * single space and leading/trailing whitespace removed, so cosmetic differences (extra spaces,
506	     * differing case) still count as the same household.
507	     *
508	     * @param lastName the last name of the owner being created
509	     * @param address the address of the owner being created
510	     * @throws DuplicateHouseholdException if an existing owner has the same last name and address
511	     */
512	    private void rejectDuplicateHousehold(String lastName, String address) {
513	        String normalizedLastName = normalizeForComparison(lastName);
514	        String normalizedAddress = normalizeForComparison(address);
515	        boolean taken = this.clinicService.findAllOwners().stream()
516	            .anyMatch(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
517	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())));
518	        if (taken) {
519	            throw new DuplicateHouseholdException(lastName, address);
520	        }
521	    }
522	
523	    /**
524	     * Assigns the owner being created into a shared household. When at least one existing owner has the
525	     * same last name and address (compared with {@link #normalizeForComparison}), the joining owner and
526	     * those existing owners are all given the same stable {@code householdId}. An existing member's id is
527	     * reused when present; otherwise a deterministic id derived from the household's last name and address
528	     * is minted, so independently created members of the same household converge on one value. When no
529	     * existing owner shares the household, no id is assigned (the owner simply founds a new address).
530	     *
531	     * @param owner the owner being created, already opted in via {@code sharesHousehold}
532	     */
533	    private void assignHousehold(Owner owner) {
534	        String normalizedLastName = normalizeForComparison(owner.getLastName());
535	        String normalizedAddress = normalizeForComparison(owner.getAddress());
536	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
537	            .filter(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
538	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())))
539	            .toList();
540	        if (housemates.isEmpty()) {
541	            return;
542	        }
543	        String householdId = housemates.stream()
544	            .map(Owner::getHouseholdId)
545	            .filter(id -> id != null && !id.isBlank())
546	            .findFirst()
547	            .orElseGet(() -> householdIdFor(normalizedLastName, normalizedAddress));
548	        owner.setHouseholdId(householdId);
549	        for (Owner housemate : housemates) {
550	            if (!householdId.equals(housemate.getHouseholdId())) {
551	                housemate.setHouseholdId(householdId);
552	                this.clinicService.saveOwner(housemate);
553	            }
554	        }
555	    }
556	
557	    /**
558	     * Derives a stable household identifier from the normalized last name and address of a household, as
559	     * the first 16 hex characters of the SHA-256 digest of {@code '<lastName>|<address>'}. The value is
560	     * deterministic, so any owner independently joining the same household computes the same identifier.
561	     *
562	     * @param normalizedLastName the household's last name, already normalized for comparison
563	     * @param normalizedAddress the household's address, already normalized for comparison
564	     * @return a stable, shareable household identifier
565	     */
566	    private String householdIdFor(String normalizedLastName, String normalizedAddress) {
567	        String key = normalizedLastName + "|" + normalizedAddress;
568	        try {
569	            byte[] digest = MessageDigest.getInstance("SHA-256")
570	                .digest(key.getBytes(StandardCharsets.UTF_8));
571	            StringBuilder sb = new StringBuilder(digest.length * 2);
572	            for (byte b : digest) {
573	                sb.append(String.format("%02x", b));
574	            }
575	            return sb.substring(0, 16);
576	        } catch (NoSuchAlgorithmException e) {
577	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
578	        }
579	    }
580	
581	    /**
582	     * Normalizes a value for household-identity comparison: leading and trailing whitespace is
583	     * removed, internal runs of whitespace are collapsed to a single space, and the result is
584	     * lower-cased.
585	     *
586	     * @param value the raw value to normalize (may be {@code null})
587	     * @return the normalized value, or an empty string when {@code value} is {@code null}
588	     */
589	    private String normalizeForComparison(String value) {
590	        if (value == null) {
591	            return "";
592	        }
593	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
594	    }
595	}
